import "jsr:@supabase/functions-js/edge-runtime.d.ts";
const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
const SUPABASE_ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY")!;
const ADMIN_EMAIL = "michelle11holguin@gmail.com";
const LOGIN_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"robots\" content=\"noindex,nofollow\">\n<title>Private Editor Sign In | Paws &amp; Purr Fosters</title>\n<style>\n:root{--sage:#9caf91;--sage-dark:#536b58;--sage-light:#e8eee4;--purple:#75628d;--purple-dark:#57456f;--purple-light:#eee9f4;--cream:#faf9f5;--ink:#30312f;--muted:#70736e;--line:#e1e3dc}\n*{box-sizing:border-box}body{margin:0;background:var(--cream);color:var(--ink);font:16px/1.55 system-ui,sans-serif}\n.shell{max-width:1100px;margin:auto;padding:22px clamp(16px,4vw,44px) 110px}\n.topbar{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:8px 0 24px;border-bottom:1px solid var(--line)}\n.brand{display:flex;align-items:center;gap:12px;text-decoration:none;color:inherit}.mark{display:grid;place-items:center;width:48px;height:48px;border-radius:16px;background:var(--purple-light);color:var(--purple-dark);font-weight:900}\n.brand strong,.brand small{display:block}.brand strong{font:600 19px Georgia,serif}.brand small,.eyebrow{font-size:11px;font-weight:800;letter-spacing:.14em;color:var(--sage-dark)}\n.site-link{color:var(--purple-dark);font-weight:700;text-decoration:none}\n.panel{max-width:620px;margin:12vh auto 0;padding:clamp(20px,4vw,36px);border:1px solid var(--line);border-radius:24px;background:white;box-shadow:0 12px 35px #3e43390b}\nh1{font:600 clamp(32px,5vw,46px)/1.12 Georgia,serif;margin:8px 0 14px}.intro{color:var(--muted)}\nform{margin-top:22px;padding:20px;border:1px solid var(--line);border-radius:18px;background:#fcfcfa}\nlabel{display:grid;gap:6px;margin:12px 0;color:var(--sage-dark);font-size:13px;font-weight:750}\ninput{width:100%;padding:11px 12px;border:1px solid var(--line);border-radius:11px;background:white;color:var(--ink);font:inherit}.password-wrap{display:flex;position:relative}.password-wrap input{padding-right:52px}.eye-button{position:absolute;right:5px;top:50%;transform:translateY(-50%);width:40px;height:38px;padding:5px;background:transparent;color:var(--purple-dark)}\nbutton{font:inherit;cursor:pointer;border:0;border-radius:999px;padding:12px 20px;font-weight:750;background:var(--purple);color:white}\nbutton:disabled{opacity:.5;cursor:wait}.error{color:#9a3c3c;min-height:24px}\n@media(max-width:600px){.topbar{align-items:flex-start}.site-link{font-size:13px}.panel{margin-top:8vh}}\n</style>\n</head>\n<body>\n<main class=\"shell\">\n<header class=\"topbar\">\n<a class=\"brand\" href=\"https://pawsandpurrfostersHQ.github.io/pawsandpurrfosters.com/\"><span class=\"mark\">P&amp;P</span><span><strong>Paws &amp; Purr</strong><small>PRIVATE SITE EDITOR</small></span></a>\n<a class=\"site-link\" href=\"https://pawsandpurrfostersHQ.github.io/pawsandpurrfosters.com/\" target=\"_blank\" rel=\"noopener\">View public website ↗</a>\n</header>\n<section class=\"panel\">\n<p class=\"eyebrow\">Private access</p><h1>Paws &amp; Purr Fosters Editor</h1>\n<p class=\"intro\">Log in to update your kittens, photos, and adoption events.</p>\n<form id=\"login-form\">\n<label>Username<input id=\"username\" autocomplete=\"username\" required></label>\n<label>Password<span class=\"password-wrap\"><input id=\"password\" type=\"password\" autocomplete=\"current-password\" required><button class=\"eye-button\" id=\"toggle-password\" type=\"button\" aria-label=\"Show password\" aria-pressed=\"false\">◉</button></span></label>\n<button id=\"submit\" type=\"submit\">Sign in</button><p id=\"message\" class=\"error\" role=\"status\"></p>\n</form>\n</section>\n</main>\n<script src=\"https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2\"></script>\n<script>\nconst SUPABASE_URL = \"https://ovnbbpcrwbvotyevghcx.supabase.co\";\nconst SUPABASE_KEY = \"sb_publishable_\" + \"ZXH8vHOT0p3-rgQgK280uw_BWsMJzAK\";\nconst EDITOR_URL = SUPABASE_URL + \"/functions/v1/private-editor?view=app\";\nconst auth = supabase.createClient(SUPABASE_URL, SUPABASE_KEY);\nconst form = document.getElementById(\"login-form\");\nconst message = document.getElementById(\"message\");\nconst button = document.getElementById(\"submit\");\nconst passwordInput = document.getElementById(\"password\");\nconst togglePassword = document.getElementById(\"toggle-password\");\ntogglePassword.addEventListener(\"click\", () => { const show = passwordInput.type === \"password\"; passwordInput.type = show ? \"text\" : \"password\"; togglePassword.textContent = show ? \"⊘\" : \"◉\"; togglePassword.setAttribute(\"aria-label\", show ? \"Hide password\" : \"Show password\"); });\nasync function loadEditor(token) {\n  const response = await fetch(EDITOR_URL, {method:\"GET\",headers:{Authorization:\"Bearer \"+token},cache:\"no-store\"});\n  if (!response.ok) throw new Error(\"Your account is not authorized to open this editor.\");\n  const html = await response.text();\n  if (!html.trim().toLowerCase().startsWith(\"<!doctype html\")) throw new Error(\"The editor returned an unexpected response. Please try again.\");\n  document.open(); document.write(html); document.close();\n}\n(async function restoreLogin() {\n  const {data} = await auth.auth.getSession();\n  if (data.session) {\n    try { await loadEditor(data.session.access_token); }\n    catch (error) { await auth.auth.signOut(); message.textContent = error.message; }\n  }\n})();\nform.addEventListener(\"submit\", async event => {\n  event.preventDefault();\n  if (document.getElementById(\"username\").value.trim().toLowerCase() !== \"pawsandpurrfostershq\") {\n    message.textContent = \"That username is not authorized.\"; return;\n  }\n  button.disabled = true; message.textContent = \"Signing in securely…\";\n  try {\n    const {data,error} = await auth.auth.signInWithPassword({\n      email:\"michelle11holguin@gmail.com\",\n      password:document.getElementById(\"password\").value\n    });\n    if (error) throw error;\n    if (data.user?.email?.toLowerCase() !== \"michelle11holguin@gmail.com\") throw new Error(\"This account is not authorized.\");\n    await loadEditor(data.session.access_token);\n  } catch (error) {\n    message.textContent = error.message || \"Sign-in failed.\"; button.disabled = false;\n  }\n});\n</script>\n</body>\n</html>";
const APP_HTML = "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"robots\" content=\"noindex,nofollow\"><link rel=\"icon\" type=\"image/png\" href=\"https://pawsandpurrfostersHQ.github.io/pawsandpurrfosters.com/assets/main-logo.PNG\"><link rel=\"apple-touch-icon\" href=\"https://pawsandpurrfostersHQ.github.io/pawsandpurrfosters.com/assets/main-logo.PNG\"><title>Private Editor | Paws &amp; Purr Fosters</title><style>:root{--sage:#9caf91;--sage-dark:#536b58;--sage-light:#e8eee4;--purple:#75628d;--purple-dark:#57456f;--purple-light:#eee9f4;--cream:#faf9f5;--ink:#30312f;--muted:#70736e;--line:#e1e3dc}*{box-sizing:border-box}body{margin:0;background:var(--cream);color:var(--ink);font:16px/1.55 \"DM Sans\",system-ui,sans-serif}.shell{max-width:1100px;margin:auto;padding:22px clamp(16px,4vw,44px) 110px}.topbar,.brand,.welcome,.section-head,.dialog-head,.publish-bar{display:flex;align-items:center;justify-content:space-between;gap:16px}.topbar{padding:8px 0 24px;border-bottom:1px solid var(--line)}.brand{justify-content:flex-start;text-decoration:none;color:inherit}.mark{display:grid;place-items:center;width:48px;height:48px;border-radius:16px;background:var(--purple-light);color:var(--purple-dark);font-weight:900}.brand strong,.brand small{display:block}.brand strong{font-family:Georgia,serif;font-size:19px}.brand small,.eyebrow{font-size:11px;font-weight:800;letter-spacing:.14em;color:var(--sage-dark)}.site-link{color:var(--purple-dark);font-weight:700;text-decoration:none}.panel{margin-top:24px;padding:clamp(20px,4vw,36px);border:1px solid var(--line);border-radius:24px;background:white;box-shadow:0 12px 35px #3e43390b}.login-panel{max-width:620px;margin:12vh auto 0}.login-panel h1,.welcome h1{font:600 clamp(32px,5vw,46px)/1.12 Georgia,serif;margin:8px 0 14px}.login-panel>p:not(.eyebrow){color:var(--muted)}button{font:inherit;cursor:pointer;border:0;border-radius:999px;padding:12px 20px;font-weight:750}.primary{background:var(--purple);color:white}.secondary{background:var(--sage-light);color:var(--sage-dark)}.quiet{background:transparent;color:var(--purple-dark);border:1px solid var(--line)}button:disabled{opacity:.45;cursor:not-allowed}.muted{color:var(--muted)}.tabs{display:flex;gap:8px;overflow:auto;padding:20px 0 2px}.tab{white-space:nowrap;background:white;border:1px solid var(--line);color:var(--muted)}.tab.active{background:var(--purple-light);border-color:#d8cde5;color:var(--purple-dark)}.view h2{font:600 30px Georgia,serif;margin:4px 0 8px}.record-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px;margin-top:22px}.record{display:flex;align-items:center;gap:12px;text-align:left;padding:12px;border:1px solid var(--line);border-radius:16px;background:white;color:var(--ink)}.record img{width:58px;height:58px;border-radius:12px;object-fit:cover;background:var(--sage-light)}.record strong,.record small{display:block}.record small{color:var(--muted)}.meet-record-row{justify-content:space-between}.record-main{display:flex;flex:1;align-items:center;gap:12px;text-align:left;border:0;background:transparent;color:inherit;padding:0;min-width:0}.meet-record-row>.quiet{flex:0 0 auto}.notice{margin-top:24px;padding:14px 16px;border-radius:14px;background:var(--sage-light);color:var(--sage-dark)}.summary-list{display:grid;gap:10px;margin-top:18px}.summary-item{padding:14px 16px;border:1px solid var(--line);border-radius:14px}.publish-bar{position:fixed;z-index:5;bottom:0;left:0;right:0;padding:14px max(16px,calc((100vw - 1012px)/2));background:#fffF;border-top:1px solid var(--line);backdrop-filter:blur(12px)}.publish-bar span{margin-right:auto;color:var(--muted);font-size:13px}.preview-dialog{width:min(1280px,96vw);height:94vh;max-height:94vh;overflow:hidden;border:1px solid var(--line);border-radius:22px;padding:18px}.preview-dialog #preview-content{height:calc(94vh - 66px);min-height:0}.preview-dialog #preview-frame{display:block;width:100%;height:100%;border:1px solid var(--line);border-radius:14px;background:white}.preview-dialog #preview-content{display:flex;justify-content:center;overflow:auto;background:#f4f3f0;border-radius:14px}.preview-dialog #preview-frame{flex:0 0 100%;max-width:100%;transition:width .2s ease,flex-basis .2s ease}.preview-dialog #preview-frame.is-mobile{flex:0 0 390px;width:390px;max-width:calc(100% - 20px)}.preview-tools{display:flex;align-items:center;gap:7px}.preview-tools button{padding:9px 13px;font-size:13px}.preview-dialog #preview-content{height:calc(94vh - 105px)}.preview-dialog::backdrop{background:#24212688}.dialog-head{margin-bottom:18px}.dialog-head h2{margin:0}@media(max-width:600px){.topbar{align-items:flex-start}.site-link{font-size:13px}.welcome{align-items:flex-start}.publish-bar{flex-wrap:wrap}.publish-bar span{flex-basis:100%}.publish-bar button{flex:1;padding:11px 10px}.login-panel{margin-top:8vh}}\n/* Editor form controls */\n.editor-form{margin-top:22px;padding:20px;border:1px solid var(--line);border-radius:18px;background:#fcfcfa}\n.editor-form h3{font:600 23px Georgia,serif;margin:16px 0 10px}\n.form-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}\n.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px;margin:16px 0}\n.editor-form label{display:grid;gap:6px;color:var(--sage-dark);font-size:13px;font-weight:750}\n.editor-form input,.editor-form textarea,.editor-form select{width:100%;min-width:0;padding:11px 12px;border:1px solid var(--line);border-radius:11px;background:white;color:var(--ink);font:inherit;font-weight:450}\n.editor-form textarea{resize:vertical}\n.photo-row{display:flex;align-items:center;gap:8px;margin:9px 0;padding:9px;border:1px solid var(--line);border-radius:12px;background:white}\n.photo-row img{width:48px;height:48px;object-fit:cover;border-radius:9px}\n.photo-row span{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:13px}.photo-file-label{display:block}.editor-form{scroll-margin-top:18px}#alumni-editor{scroll-margin-top:18px}\n.photo-row button{padding:8px 11px;background:var(--purple-light);color:var(--purple-dark);font-size:13px}\n.upload-label{margin:14px 0}\n@media(max-width:600px){.fields{grid-template-columns:1fr}.photo-row{flex-wrap:wrap}.photo-row span{flex-basis:calc(100% - 60px)}}\n</style><style>.collapsible{padding:0;overflow:hidden}.collapsible>summary{display:flex;align-items:center;justify-content:space-between;gap:14px;list-style:none;cursor:pointer;padding:18px 20px;user-select:none}.collapsible>summary::-webkit-details-marker{display:none}.collapsible>summary h3,.collapsible>summary h4{margin:2px 0 4px}.collapsible>summary p{margin:0}.collapsible>summary small{display:block;margin-top:3px}.collapsible[open]>summary{border-bottom:1px solid var(--line);margin-bottom:16px}.collapsible .collapse-indicator{display:grid;place-items:center;width:30px;height:30px;flex:0 0 30px;border-radius:50%;background:var(--purple-light);color:var(--purple-dark);transition:transform .18s ease}.collapsible[open] .collapse-indicator{transform:rotate(180deg)}</style></head><body>\n  <main class=\"shell\">\n    <header class=\"topbar\">\n      <a class=\"brand\" href=\"https://pawsandpurrfostersHQ.github.io/pawsandpurrfosters.com/\"><span class=\"mark\">P&amp;P</span><span><strong>Paws &amp; Purr</strong><small>PRIVATE SITE EDITOR</small></span></a>\n      <a class=\"site-link\" href=\"https://pawsandpurrfostersHQ.github.io/pawsandpurrfosters.com/\" target=\"_blank\" rel=\"noopener\">View public website ↗</a>\n    </header>\n    <section id=\"login\" class=\"panel login-panel\" hidden>\n      <p class=\"eyebrow\">Private access</p>\n      <h1>Your foster website, in your hands.</h1>\n      <p>Sign in with your private editor username and password.</p>\n      <form id=\"login-form\" class=\"editor-form\">\n        <label>Username<input id=\"login-username\" name=\"username\" autocomplete=\"username\" required></label>\n        <label>Password<input id=\"login-password\" name=\"password\" type=\"password\" autocomplete=\"current-password\" required></label>\n        <button id=\"sign-in\" class=\"primary\" type=\"submit\">Sign in</button>\n      </form>\n      <p id=\"login-message\" class=\"muted\" role=\"status\">Secure sign-in setup is in progress. Your password is sent directly to Supabase Auth, not stored by this page.</p>\n    </section>\n    <section id=\"dashboard\">\n      <div class=\"welcome\"><div><p class=\"eyebrow\">Your workspace</p><h1>Your Paws &amp; Purr workspace</h1><p class=\"muted\">Changes will be previewed before they are published.</p></div><button id=\"sign-out\" class=\"quiet\" type=\"button\">Sign out</button></div>\n      <nav class=\"tabs\" aria-label=\"Editor sections\">\n        <button class=\"tab active\" data-view=\"kittens\">Kitten profiles</button>\n        <button class=\"tab\" data-view=\"photos\">Homepage photos</button>\n        <button class=\"tab\" data-view=\"events\">Events</button>\n        <button class=\"tab\" data-view=\"alumni\">Foster alumni</button>\n        <button class=\"tab\" data-view=\"meet-greets\">Meet &amp; Greets</button>\n      </nav>\n      <section id=\"view-kittens\" class=\"panel view\">\n        <div class=\"section-head\"><div><p class=\"eyebrow\">Profiles</p><h2>Current fosters</h2><p class=\"muted\">Choose a kitten to edit their details and photo gallery.</p></div></div>\n        <div id=\"kitten-list\" class=\"record-list\"></div>\n      </section>\n      <section id=\"view-photos\" class=\"panel view\" hidden><p class=\"eyebrow\">Homepage carousel</p><h2>Foster photos</h2><p class=\"muted\">These are the exact photos in your homepage carousel. Preview them, add new photos, remove any you no longer want, and move them into the order you prefer.</p><div id=\"hero-photo-list\" class=\"record-list\"></div><label class=\"upload-label\">Add photos to the homepage carousel<input id=\"hero-upload\" type=\"file\" accept=\"image/jpeg,image/png,image/webp,image/gif\" multiple></label></section>\n      <section id=\"view-events\" class=\"panel view\" hidden><p class=\"eyebrow\">Adoption events</p><h2>Events and locations</h2><p class=\"muted\">Your current event information is loaded from the public website. Update the details here, preview them, and publish only when you are ready.</p><div id=\"event-summary\"></div></section>\n      <section id=\"view-meet-greets\" class=\"panel view\" hidden>\n        <p class=\"eyebrow\">Private appointments</p><h2>Meet &amp; Greets</h2>\n        <p class=\"muted\">Review requests, approve or decline, add the meeting location, and keep track of confirmed visits.</p>\n        <div class=\"section-head\"><div class=\"form-actions\"><button id=\"refresh-meet-greets\" class=\"secondary\" type=\"button\">Refresh requests</button><button id=\"clear-meet-greets\" class=\"quiet\" type=\"button\">Clear all requests</button></div><span id=\"meet-greet-admin-status\" class=\"muted\" role=\"status\"></span></div>\n        <details class=\"editor-form collapsible\" id=\"meet-requests-card\"><summary><span><p class=\"eyebrow\">Appointment management</p><h3>Appointment Requests</h3><small class=\"muted\">Open to review requests</small></span><span class=\"collapse-indicator\" aria-hidden=\"true\">⌄</span></summary>\n          <div id=\"meet-greet-admin-list\" class=\"record-list\"></div><div id=\"meet-greet-admin-detail\"></div></details>\n        <details class=\"editor-form collapsible\" id=\"meet-conflicts-card\"><summary><span><p class=\"eyebrow\">Adoption-event scheduling</p><h3>Event Conflicts</h3><small class=\"muted\">Visitor responses and rescheduling</small></span><span class=\"collapse-indicator\" aria-hidden=\"true\">⌄</span></summary><p class=\"muted\">See which visitors were contacted and whether they chose the adoption event or a private reschedule.</p><div id=\"meet-event-conflict-list\" class=\"record-list\"><p class=\"muted\">Loading event conflicts…</p></div></details>\n        <details class=\"editor-form collapsible\" id=\"meet-availability-card\">\n          <summary><span><p class=\"eyebrow\">Your schedule</p><h3>My Availability</h3><small class=\"muted\">Manage saved availability rules</small></span><span class=\"collapse-indicator\" aria-hidden=\"true\">⌄</span></summary>\n          <p class=\"muted\">Set recurring weekday availability over a date range. Special availability creates two-hour visits with a daily booking limit.</p>\n          <div class=\"fields\">\n            <label>Rule type<select id=\"meet-av-mode\"><option value=\"special\">Special availability (2-hour visits)</option><option value=\"unavailable\">Unavailable</option></select></label>\n            <label>Daily appointment limit<input id=\"meet-av-max\" type=\"number\" min=\"1\" max=\"4\" value=\"2\"></label>\n            <label>Start date<input id=\"meet-av-start\" type=\"date\" required></label>\n            <label>End date<input id=\"meet-av-end\" type=\"date\" required></label>\n            <label>Available from<input id=\"meet-av-time-start\" type=\"time\" step=\"1800\" value=\"11:00\"></label>\n            <label>Appointments must end by<input id=\"meet-av-time-end\" type=\"time\" step=\"1800\" value=\"16:00\"></label>\n          </div>\n          <p class=\"muted\">Choose the weekdays this rule applies to:</p>\n          <div class=\"fields\" id=\"meet-av-weekdays\">\n            <label><input type=\"checkbox\" value=\"0\"> Sunday</label><label><input type=\"checkbox\" value=\"1\"> Monday</label><label><input type=\"checkbox\" value=\"2\"> Tuesday</label><label><input type=\"checkbox\" value=\"3\"> Wednesday</label><label><input type=\"checkbox\" value=\"4\"> Thursday</label><label><input type=\"checkbox\" value=\"5\"> Friday</label><label><input type=\"checkbox\" value=\"6\"> Saturday</label>\n          </div>\n          <label>Note shown to visitors<textarea id=\"meet-av-note\" rows=\"2\" maxlength=\"500\" placeholder=\"Appointments on this date are limited to two hours due to special scheduling.\"></textarea></label>\n          <div class=\"form-actions\"><button class=\"primary\" id=\"meet-av-save\" type=\"button\">Save availability rule</button><button class=\"quiet\" id=\"meet-av-reset\" type=\"button\">Clear form</button><span id=\"meet-av-status\" class=\"muted\" role=\"status\"></span></div>\n          <h4>Saved availability rules</h4><div id=\"meet-av-rules\" class=\"record-list\"></div>\n        </details>\n      </section>\n      <section id=\"view-alumni\" class=\"panel view\" hidden><p class=\"eyebrow\">Adoption milestones</p><h2>Foster alumni</h2><p class=\"muted\">All existing foster alumni records are loaded below. Select a kitten to review or edit their saved information. Birthday and Gotcha Day previews are included.</p><div id=\"alumni-summary\"></div></section>\n      <div class=\"publish-bar\"><span id=\"save-status\">Preview mode — no changes are being published.</span><button id=\"preview\" class=\"secondary\" type=\"button\">Preview changes</button><button id=\"publish\" class=\"primary\" type=\"button\" disabled>Publish changes</button></div>\n    </section>\n  </main>\n  <dialog id=\"preview-dialog\" class=\"preview-dialog\"><div class=\"dialog-head\"><div><h2>Website preview</h2><p class=\"muted\">Latest live design with your unpublished editor changes.</p></div><div class=\"preview-tools\"><button id=\"preview-desktop\" class=\"quiet\" type=\"button\">Desktop</button><button id=\"preview-mobile\" class=\"quiet\" type=\"button\">Mobile</button><button id=\"close-preview\" class=\"quiet\" type=\"button\">Close</button></div></div><div id=\"preview-content\"><iframe id=\"preview-frame\" title=\"Paws &amp; Purr website preview\"></iframe></div></dialog>\n  <script src=\"https://pawsandpurrfostersHQ.github.io/pawsandpurrfosters.com/kitten-data.js\"></script>\n  <script src=\"https://pawsandpurrfostersHQ.github.io/pawsandpurrfosters.com/event-data.js\"></script>\n  <script src=\"https://pawsandpurrfostersHQ.github.io/pawsandpurrfosters.com/alumni-data.js\"></script>\n  <script src=\"https://pawsandpurrfostersHQ.github.io/pawsandpurrfosters.com/script.js\"></script>\n  <script src=\"https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2\"></script>\n  <script>window.PAWS_SUPABASE_CONFIG={url:\"https://ovnbbpcrwbvotyevghcx.supabase.co\",publishableKey:\"sb_publishable_ZXH8vHOT0p3-rgQgK280uw_BWsMJzAK\"};</script>\n  <script>/* Editor prototype: changes remain in this browser session until secure publishing is installed. */\n(() => {\n  const $ = s => document.querySelector(s);\n  const clone = value => JSON.parse(JSON.stringify(value));\n  const draft = {\n    kittens: clone(window.PAWS_KITTENS || []),\n    events: clone(window.PAWS_EVENT_DATA || {}),\n    alumni: clone(window.PAWS_FOSTER_ALUMNI || []),\n    heroPhotos: [...(window.PAWS_FOSTER_CAROUSEL_PHOTOS || [])]\n  };\n  let selectedId = null, dirty = false;\n  const authConfig = window.PAWS_SUPABASE_CONFIG || {};\n  const supabaseReady = !!(window.supabase && authConfig.url && authConfig.publishableKey &&\n    !String(authConfig.url).includes(\"YOUR_\") && !String(authConfig.publishableKey).includes(\"YOUR_\"));\n  const supabaseClient = supabaseReady\n    ? window.supabase.createClient(authConfig.url, authConfig.publishableKey)\n    : null;\n  const ADMIN_USERNAME = \"pawsandpurrfosters\";\n  const ADMIN_EMAIL = \"michelle11holguin@gmail.com\";\n  async function restoreSession() {\n    if (!supabaseClient) return;\n    const { data, error } = await supabaseClient.auth.getSession();\n    if (error) return;\n    if (data.session && data.session.user?.email?.toLowerCase() === ADMIN_EMAIL) {\n      $(\"#login\").hidden = true;\n      $(\"#dashboard\").hidden = false;\n    } else if (data.session) {\n      await supabaseClient.auth.signOut();\n    }\n  }\n  $(\"#login-form\")?.addEventListener(\"submit\", async event => {\n    event.preventDefault();\n    const username = $(\"#login-username\").value.trim().toLowerCase();\n    const password = $(\"#login-password\").value;\n    const message = $(\"#login-message\");\n    if (!supabaseClient) {\n      message.textContent = \"Supabase connection is not configured yet. The editor remains locked.\";\n      return;\n    }\n    if (username !== ADMIN_USERNAME) {\n      message.textContent = \"That username is not authorized.\";\n      return;\n    }\n    $(\"#sign-in\").disabled = true;\n    message.textContent = \"Signing in securely…\";\n    try {\n      const { data, error } = await supabaseClient.auth.signInWithPassword({ email: ADMIN_EMAIL, password });\n      if (error) throw error;\n      if (data.user?.email?.toLowerCase() !== ADMIN_EMAIL) {\n        await supabaseClient.auth.signOut();\n        throw new Error(\"This account is not authorized for the private editor.\");\n      }\n      $(\"#login\").hidden = true;\n      $(\"#dashboard\").hidden = false;\n      message.textContent = \"\";\n      $(\"#login-password\").value = \"\";\n    } catch (error) {\n      message.textContent = error.message || \"Sign-in failed. Please check your details.\";\n    } finally {\n      $(\"#sign-in\").disabled = false;\n    }\n  });\n  const esc = value => String(value ?? \"\").replace(/[&<>\"']/g,c=>({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]));\n  let markDirty = () => { dirty=true; $(\"#save-status\").textContent=\"You have unpublished draft changes in this session.\"; };\n  $(\"#sign-out\").addEventListener(\"click\",async()=>{\n    if (supabaseClient) await supabaseClient.auth.signOut();\n    $(\"#dashboard\").hidden=true; $(\"#login\").hidden=false;\n  });\n  restoreSession();\n  document.querySelectorAll(\".tab\").forEach(tab=>tab.addEventListener(\"click\",()=>{\n    document.querySelectorAll(\".tab\").forEach(x=>x.classList.toggle(\"active\",x===tab));\n    document.querySelectorAll(\".view\").forEach(x=>x.hidden=x.id!==\"view-\"+tab.dataset.view);\n  }));\n  const meetAdminList = $(\"#meet-greet-admin-list\");\n  const meetAdminStatus = $(\"#meet-greet-admin-status\");\n  const meetAdminDetail = $(\"#meet-greet-admin-detail\");\n  let meetAdminRows=[];\n  async function meetAdminCall(payload) {\n    if (!supabaseClient) throw new Error(\"Please sign in again.\");\n    const { data:{session} } = await supabaseClient.auth.getSession();\n    if (!session?.access_token) throw new Error(\"Your session expired. Please sign in again.\");\n    const response = await fetch(\"https://ovnbbpcrwbvotyevghcx.supabase.co/functions/v1/meet-greet\", {\n      method:\"POST\", headers:{\"Content-Type\":\"application/json\",\"Authorization\":\"Bearer \"+session.access_token,\"apikey\":authConfig.publishableKey},\n      body:JSON.stringify(payload)\n    });\n    const result=await response.json();\n    if(!response.ok) throw new Error(result.error||\"Could not complete the request.\");\n    return result;\n  }\n  function formatMeetDate(value) { return new Intl.DateTimeFormat(\"en-US\",{timeZone:\"America/Los_Angeles\",weekday:\"long\",month:\"long\",day:\"numeric\"}).format(new Date(value)); }\n  function formatMeetTime(value) { return new Intl.DateTimeFormat(\"en-US\",{timeZone:\"America/Los_Angeles\",hour:\"numeric\",minute:\"2-digit\"}).format(new Date(value)); }\nasync function loadEventConflicts(){\n const host=$(\"#meet-event-conflict-list\");if(!host||!supabaseClient)return;\n try{\n  const {data:{session}}=await supabaseClient.auth.getSession();\n  const response=await fetch(\"https://ovnbbpcrwbvotyevghcx.supabase.co/functions/v1/event-conflicts\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\",\"Authorization\":\"Bearer \"+session.access_token,\"apikey\":authConfig.publishableKey},body:JSON.stringify({action:\"admin-list\"})});\n  const result=await response.json();if(!response.ok)throw new Error(result.error||\"Could not load event conflicts.\");\n  const labels={awaiting_response:\"Awaiting response\",attending_event:\"Attending adoption event\",private_reschedule:\"Private meet-and-greet requested\",resolved:\"Resolved\",canceled:\"Event removed\",auto_canceled:\"Automatically canceled\"};\n  const rows=result.conflicts||[];\n  host.innerHTML=rows.length?rows.map(c=>{const a=c.appointment||{};return '<div class=\"record\"><span><strong>'+esc(a.first_name||\"Visitor\")+' '+esc(a.last_name||\"\")+'</strong><small>'+esc(a.email||\"\")+'</small><small>'+esc(c.event_title)+' · '+esc(c.event_date)+' · '+esc(c.event_location||\"Location not listed\")+'</small><small>'+esc(labels[c.status]||c.status)+'</small></span></div>';}).join(\"\"):'<p class=\"muted\">No adoption-event conflicts have been recorded.</p>';\n }catch(e){host.innerHTML='<p class=\"muted\">'+esc(e.message||\"Could not load event conflicts.\")+'</p>';}\n}\n  async function loadMeetGreets() {\n    meetAdminStatus.textContent=\"Loading…\";\n    try {\n      const result=await meetAdminCall({action:\"admin-list\"});\n      const rows=result.appointments||[];\n      meetAdminRows=rows;\n      meetAdminList.innerHTML=rows.length?rows.map(r=>'<div class=\"record meet-record-row\"><button class=\"record-main\" type=\"button\" data-meet-id=\"'+esc(r.id)+'\"><span><strong>'+esc(r.first_name+\" \"+r.last_name)+'</strong><small>'+esc(r.status===\"superseded\"?\"RESCHEDULED\":r.status.toUpperCase())+' · '+esc(formatMeetDate(r.starts_at))+' · '+esc(formatMeetTime(r.starts_at))+'–'+esc(formatMeetTime(r.ends_at))+'</small><small>'+esc((r.kittens||[]).join(\", \"))+'</small></span></button><button class=\"quiet\" type=\"button\" data-meet-delete=\"'+esc(r.id)+'\">Clear</button></div>').join(\"\"):'<p class=\"muted\">No meet-and-greet requests yet.</p>'\n      meetAdminList.querySelectorAll(\"[data-meet-id]\").forEach(b=>b.addEventListener(\"click\",()=>{showMeetDetail(rows.find(r=>r.id===b.dataset.meetId));meetAdminDetail.scrollIntoView({behavior:\"smooth\",block:\"start\"});}));\n      meetAdminList.querySelectorAll(\"[data-meet-delete]\").forEach(b=>b.addEventListener(\"click\",async()=>{if(!confirm(\"Clear this individual appointment record? This cannot be undone.\"))return;try{await meetAdminCall({action:\"admin-delete\",id:b.dataset.meetDelete});meetAdminStatus.textContent=\"Appointment record cleared.\";meetAdminDetail.innerHTML=\"\";loadMeetGreets();}catch(e){meetAdminStatus.textContent=e.message;}}));\n      meetAdminStatus.textContent=rows.length+\" appointment record(s)\";\n      loadEventConflicts();\n    } catch(e) { meetAdminStatus.textContent=e.message; }\n  }\nlet meetAvailabilityRules=[],editingAvailabilityId=\"\";\n  const meetAvStatus=$(\"#meet-av-status\"),meetAvList=$(\"#meet-av-rules\");\n  function resetAvailabilityForm(){editingAvailabilityId=\"\";$(\"#meet-av-mode\").value=\"special\";$(\"#meet-av-max\").value=\"2\";$(\"#meet-av-start\").value=\"\";$(\"#meet-av-end\").value=\"\";$(\"#meet-av-time-start\").value=\"11:00\";$(\"#meet-av-time-end\").value=\"16:00\";$(\"#meet-av-note\").value=\"\";document.querySelectorAll(\"#meet-av-weekdays input\").forEach(x=>x.checked=false);$(\"#meet-av-save\").textContent=\"Save availability rule\";toggleAvailabilityFields();}\n  function toggleAvailabilityFields(){const special=$(\"#meet-av-mode\").value===\"special\";[\"#meet-av-max\",\"#meet-av-time-start\",\"#meet-av-time-end\",\"#meet-av-note\"].forEach(id=>$(id).disabled=!special);}\n  $(\"#meet-av-mode\").addEventListener(\"change\",toggleAvailabilityFields);$(\"#meet-av-reset\").addEventListener(\"click\",resetAvailabilityForm);\n  async function loadMeetAvailability(){\n    meetAvStatus.textContent=\"Loading availability…\";\n    try{const result=await meetAdminCall({action:\"admin-availability-list\",site_base_url:window.location.origin});meetAvailabilityRules=result.rules||[];\n      meetAvList.innerHTML=meetAvailabilityRules.length?meetAvailabilityRules.map(r=>{const days=[\"Sun\",\"Mon\",\"Tue\",\"Wed\",\"Thu\",\"Fri\",\"Sat\"].filter((d,i)=>(r.weekdays||[]).includes(i)).join(\", \"),label=r.mode===\"unavailable\"?\"Unavailable\":\"Special · \"+r.start_time.slice(0,5)+\"–\"+r.cutoff_time.slice(0,5)+\" · \"+r.max_appointments+\" per day\";return '<div class=\"record meet-record-row\"><span><strong>'+esc(label)+'</strong><small>'+esc(r.start_date)+' through '+esc(r.end_date)+' · '+esc(days)+'</small></span><button class=\"quiet\" type=\"button\" data-av-edit=\"'+esc(r.id)+'\">Edit</button><button class=\"quiet\" type=\"button\" data-av-delete=\"'+esc(r.id)+'\">Remove</button></div>';}).join(\"\"):'<p class=\"muted\">No custom availability rules. Your normal schedule remains in effect.</p>';\n      meetAvList.querySelectorAll(\"[data-av-edit]\").forEach(b=>b.onclick=()=>editMeetAvailability(b.dataset.avEdit));\n      meetAvList.querySelectorAll(\"[data-av-delete]\").forEach(b=>b.onclick=async()=>{if(!confirm(\"Remove this availability rule?\"))return;try{await meetAdminCall({action:\"admin-availability-delete\",id:b.dataset.avDelete,site_base_url:window.location.origin});meetAvStatus.textContent=\"Rule removed.\";await loadMeetAvailability();}catch(e){meetAvStatus.textContent=e.message;}});\n      meetAvStatus.textContent=meetAvailabilityRules.length+\" saved rule(s).\";\n    }catch(e){meetAvStatus.textContent=e.message;}\n  }\n  function editMeetAvailability(id){const r=meetAvailabilityRules.find(x=>x.id===id);if(!r)return;editingAvailabilityId=id;$(\"#meet-av-mode\").value=r.mode;$(\"#meet-av-start\").value=r.start_date;$(\"#meet-av-end\").value=r.end_date;$(\"#meet-av-time-start\").value=(r.start_time||\"11:00\").slice(0,5);$(\"#meet-av-time-end\").value=(r.cutoff_time||\"16:00\").slice(0,5);$(\"#meet-av-max\").value=r.max_appointments||2;$(\"#meet-av-note\").value=r.note||\"\";document.querySelectorAll(\"#meet-av-weekdays input\").forEach(x=>x.checked=(r.weekdays||[]).includes(Number(x.value)));$(\"#meet-av-save\").textContent=\"Update availability rule\";toggleAvailabilityFields();$(\"#meet-availability-card\").scrollIntoView({behavior:\"smooth\",block:\"start\"});}\n  $(\"#meet-av-save\").addEventListener(\"click\",async()=>{const weekdays=[...document.querySelectorAll(\"#meet-av-weekdays input:checked\")].map(x=>Number(x.value)),mode=$(\"#meet-av-mode\").value,payload={action:\"admin-availability-save\",id:editingAvailabilityId||undefined,site_base_url:window.location.origin,start_date:$(\"#meet-av-start\").value,end_date:$(\"#meet-av-end\").value,weekdays,mode,start_time:$(\"#meet-av-time-start\").value,cutoff_time:$(\"#meet-av-time-end\").value,max_appointments:Number($(\"#meet-av-max\").value),note:$(\"#meet-av-note\").value};const button=$(\"#meet-av-save\");button.disabled=true;meetAvStatus.textContent=\"Saving…\";try{await meetAdminCall(payload);meetAvStatus.textContent=\"Availability rule saved.\";resetAvailabilityForm();await loadMeetAvailability();}catch(e){meetAvStatus.textContent=e.message;}finally{button.disabled=false;}});\n    function showMeetDetail(r) {\n    if(!r)return;\n    const pending=r.status===\"pending\",confirmed=r.status===\"confirmed\",previous=r.reschedules_appointment_id?meetAdminRows.find(x=>x.id===r.reschedules_appointment_id):null;\n    meetAdminDetail.innerHTML='<section class=\"editor-form\"><div class=\"form-heading\"><h3>'+esc(r.first_name+\" \"+r.last_name)+'</h3><strong>'+esc(r.status===\"superseded\"?\"RESCHEDULED\":r.status.toUpperCase())+'</strong></div><p><b>Email:</b> '+esc(r.email)+'</p>'+(previous?'<p><b>Previous confirmed date:</b> '+esc(formatMeetDate(previous.starts_at))+'</p><p><b>Previous confirmed window:</b> '+esc(formatMeetTime(previous.starts_at))+' to '+esc(formatMeetTime(previous.ends_at))+'</p>':'')+'<p><b>Requested date:</b> '+esc(formatMeetDate(r.starts_at))+'</p><p><b>Reserved window:</b> '+esc(formatMeetTime(r.starts_at))+' to '+esc(formatMeetTime(r.ends_at))+' ('+((new Date(r.ends_at)-new Date(r.starts_at))/3600000)+'-hour visit)</p><p><b>Kittens:</b> '+esc((r.kittens||[]).join(\", \"))+'</p><p><b>Application submitted:</b> '+(r.application_submitted?\"Yes\":\"No\")+'</p><p><b>Notes:</b> '+esc(r.additional_notes||\"None\")+'</p>'+(r.reschedules_appointment_id?'<p><b>Reschedule request:</b> This is a request to change an existing appointment.</p>':'')+(r.reschedule_reason?'<p><b>Reschedule reason:</b> '+esc(r.reschedule_reason)+'</p>':'')+(r.cancellation_reason?'<p><b>Cancellation reason:</b> '+esc(r.cancellation_reason)+'</p><p><b>Canceled by:</b> '+(r.cancellation_actor==='visitor'?'Visitor':'Foster / admin')+'</p>':'')+(pending?'<div class=\"fields\"><label>Choose a saved location<select id=\"meet-location-choice\" required><option value=\"\">Choose a meeting location</option><option value=\"foster\">Paws &amp; Purr Foster Home</option><option value=\"rescue\">Rescue Vice President’s Home</option><option value=\"custom\">Other location — enter manually</option></select></label><label>Meeting location name<input id=\"meet-location\" maxlength=\"160\" placeholder=\"Choose a saved location or enter a custom name\" required></label><label>Full address<input id=\"meet-address\" maxlength=\"500\" placeholder=\"Street, city, state\" required></label><label>Directions / parking / instructions<textarea id=\"meet-instructions\" maxlength=\"1000\" rows=\"3\"></textarea></label><label>Personal message to visitor<textarea id=\"meet-message\" maxlength=\"1000\" rows=\"2\" placeholder=\"Okay, see you soon!\"></textarea></label></div><div class=\"form-actions\"><button id=\"meet-approve\" class=\"primary\" type=\"button\">Approve &amp; send confirmation</button><button id=\"meet-decline\" class=\"quiet\" type=\"button\">Decline request</button></div>':'')+(confirmed||r.status===\"superseded\"?'<div class=\"editor-form\"><p><b>Location:</b> '+esc(r.location_name||\"\")+' — '+esc(r.location_address||\"\")+'</p><p><b>Instructions:</b> '+esc(r.location_instructions||\"\")+'</p><p class=\"muted\">The visitor will receive a standard cancellation email. This time slot will be removed from future booking availability.</p><button id=\"meet-admin-cancel\" class=\"quiet\" type=\"button\">Cancel appointment &amp; notify visitor</button><button id=\"meet-complete\" class=\"secondary\" type=\"button\">Mark completed</button></div>':'')+'</section>';\n    $(\"#meet-location-choice\")?.addEventListener(\"change\",event=>{const choice=event.target.value;const presets={foster:{name:\"Paws & Purr Foster Home\",address:\"4221 Palomar Dr, Antioch, CA\"},rescue:{name:\"Rescue Vice President’s Home\",address:\"1441 Gamay Circle, Oakley, CA\"}};const item=presets[choice];$(\"#meet-location\").value=item?.name||\"\";$(\"#meet-address\").value=item?.address||\"\";if(choice===\"custom\")$(\"#meet-location\").focus();});\n    $(\"#meet-approve\")?.addEventListener(\"click\",async()=>{if(!$(\"#meet-location\").value.trim()||!$(\"#meet-address\").value.trim()){meetAdminStatus.textContent=\"Choose a meeting location and enter its full address before approving.\";return;}try{await meetAdminCall({action:\"admin-review\",id:r.id,decision:\"approve\",location_name:$(\"#meet-location\").value,location_address:$(\"#meet-address\").value,location_instructions:$(\"#meet-instructions\").value,personal_message:$(\"#meet-message\").value});meetAdminStatus.textContent=\"Appointment confirmed and email sent.\";meetAdminDetail.innerHTML=\"\";loadMeetGreets();}catch(e){meetAdminStatus.textContent=e.message;}});\n    $(\"#meet-decline\")?.addEventListener(\"click\",async()=>{if(!confirm(\"Decline this request and notify the visitor?\"))return;try{await meetAdminCall({action:\"admin-review\",id:r.id,decision:\"decline\"});meetAdminStatus.textContent=\"Request declined.\";meetAdminDetail.innerHTML=\"\";loadMeetGreets();}catch(e){meetAdminStatus.textContent=e.message;}});\n    $(\"#meet-admin-cancel\")?.addEventListener(\"click\",async()=>{if(!confirm(\"Cancel this confirmed appointment, block this time from future bookings, and email the visitor?\"))return;try{await meetAdminCall({action:\"admin-cancel\",id:r.id});meetAdminStatus.textContent=\"Appointment canceled, time slot blocked, and visitor notified.\";meetAdminDetail.innerHTML=\"\";loadMeetGreets();}catch(e){meetAdminStatus.textContent=e.message;}});\n    $(\"#meet-complete\")?.addEventListener(\"click\",async()=>{try{await meetAdminCall({action:\"admin-complete\",id:r.id});meetAdminStatus.textContent=\"Marked completed.\";loadMeetGreets();}catch(e){meetAdminStatus.textContent=e.message;}});\n  }\n  $(\"#refresh-meet-greets\")?.addEventListener(\"click\",loadMeetGreets);\n  $(\"#clear-meet-greets\")?.addEventListener(\"click\",async()=>{if(!confirm(\"Permanently delete ALL appointment records, including pending, confirmed, completed, and test records? This cannot be undone.\"))return;if(!confirm(\"Please confirm one more time: clear every appointment record?\"))return;try{await meetAdminCall({action:\"admin-clear\"});meetAdminStatus.textContent=\"All appointment records cleared.\";meetAdminDetail.innerHTML=\"\";loadMeetGreets();}catch(e){meetAdminStatus.textContent=e.message;}});\n  document.querySelector('[data-view=\"meet-greets\"]')?.addEventListener(\"click\",()=>{loadMeetGreets();loadMeetAvailability();});\n  function renderKittenList(){\n    $(\"#kitten-list\").innerHTML=draft.kittens.map(k=>`<button class=\"record\" data-kitten=\"${esc(k.id)}\"><img src=\"https://pawsandpurrfostersHQ.github.io/pawsandpurrfosters.com/${esc(k.image)}\" alt=\"\"><span><strong>${esc(k.name)}</strong><small>${esc(k.status||k.adoptionStatus||\"\")}</small></span></button>`).join(\"\");\n    document.querySelectorAll(\"[data-kitten]\").forEach(b=>b.addEventListener(\"click\",()=>editKitten(b.dataset.kitten)));\n  }\n  function editKitten(id){\n    selectedId=id; const k=draft.kittens.find(x=>x.id===id); if(!k)return;\n    $(\"#kitten-editor\")?.remove();\n    const form=document.createElement(\"section\");form.id=\"kitten-editor\";form.className=\"editor-form\";\n    const fields=[[\"name\",\"Name\"],[\"birthday\",\"Birthday\",\"date\"],[\"gender\",\"Gender\"],[\"litterNumber\",\"Foster litter number\",\"number\"],[\"image\",\"Main profile photo path\"],[\"description\",\"Card description\"],[\"bio\",\"Bio\",\"textarea\"],[\"idealHome\",\"Ideal home\",\"textarea\"],[\"petfinderUrl\",\"Petfinder link\"],[\"status\",\"Adoption status\"]];\n    form.innerHTML=`<div class=\"form-heading\"><div><p class=\"eyebrow\">Editing profile</p><h3>${esc(k.name)}</h3></div><button type=\"button\" class=\"quiet\" id=\"close-kitten\">Close</button></div><div class=\"fields\">${fields.map(([key,label,type])=>`<label>${label}${type===\"textarea\"?`<textarea data-field=\"${key}\" rows=\"5\">${esc(k[key])}</textarea>`:`<input data-field=\"${key}\" type=\"${type||\"text\"}\" value=\"${esc(k[key])}\">`}</label>`).join(\"\")}<label>Dogs<select data-compat=\"dogs\">${options([\"Unknown — no direct experience\",\"Yes\",\"Yes — with proper introduction\",\"No\",\"Possibly — no direct experience\"],k.compatibility?.dogs)}</select></label><label>Cats<select data-compat=\"cats\">${options([\"Unknown — no direct experience\",\"Yes\",\"Yes — with proper introduction\",\"No\",\"Prefers to be the only cat\"],k.compatibility?.cats)}</select></label><label>Younger children<select data-compat=\"youngerChildren\">${options([\"Unknown — no direct experience\",\"Yes\",\"Possibly — no direct experience\",\"No\"],k.compatibility?.youngerChildren)}</select></label><label>Older children<select data-compat=\"olderChildren\">${options([\"Unknown — no direct experience\",\"Yes\",\"Possibly — no direct experience\",\"No\"],k.compatibility?.olderChildren)}</select></label></div><h4>Profile photo gallery</h4><p class=\"muted\">Add photos from your device. They will be saved to the private draft branch when you publish.</p><div id=\"profile-photos\"></div><label class=\"upload-label\">Choose additional photos<input id=\"profile-upload\" type=\"file\" accept=\"image/jpeg,image/png,image/webp,image/gif\" multiple></label><button type=\"button\" class=\"primary\" id=\"save-kitten-draft\">Save profile draft</button>`;\n    $(\"#view-kittens\").append(form);\n    requestAnimationFrame(()=>form.scrollIntoView({behavior:\"smooth\",block:\"start\"}));\n    $(\"#close-kitten\").onclick=()=>form.remove();\n    form.querySelectorAll(\"[data-field]\").forEach(input=>input.addEventListener(\"input\",()=>{k[input.dataset.field]=input.type===\"number\"?Number(input.value):input.value;}));\n    form.querySelectorAll(\"[data-compat]\").forEach(input=>input.addEventListener(\"change\",()=>{k.compatibility ||= {};k.compatibility[input.dataset.compat]=input.value;}));\n    const renderPhotos=()=>{$(\"#profile-photos\").innerHTML=(k.photos||[]).map((p,i)=>`<div class=\"photo-row\"><img src=\"${p.startsWith(\"blob:\")?esc(p):\"https://pawsandpurrfostersHQ.github.io/pawsandpurrfosters.com/\"+esc(p)}\" alt=\"\"><span>${esc(p.split(\"/\").pop())}</span><button type=\"button\" data-main-photo=\"${i}\" ${k.image===p?\"disabled\":\"\"}>Set as main</button><button type=\"button\" data-up=\"${i}\" ${i===0?\"disabled\":\"\"}>↑</button><button type=\"button\" data-down=\"${i}\" ${i===k.photos.length-1?\"disabled\":\"\"}>↓</button><button type=\"button\" data-remove=\"${i}\">Remove</button></div>`).join(\"\");form.querySelectorAll(\"[data-up]\").forEach(b=>b.onclick=()=>move(Number(b.dataset.up),-1));form.querySelectorAll(\"[data-down]\").forEach(b=>b.onclick=()=>move(Number(b.dataset.down),1));form.querySelectorAll(\"[data-main-photo]\").forEach(b=>b.onclick=()=>{k.image=k.photos[Number(b.dataset.mainPhoto)];const mainInput=form.querySelector('[data-field=\"image\"]');if(mainInput)mainInput.value=k.image;renderPhotos();markDirty();});form.querySelectorAll(\"[data-remove]\").forEach(b=>b.onclick=()=>{const removed=k.photos.splice(Number(b.dataset.remove),1)[0];if(removed?.startsWith(\"blob:\")){URL.revokeObjectURL(removed);pendingPhotoUploads.delete(removed);}renderPhotos();markDirty();});};\n    function move(i,d){[k.photos[i],k.photos[i+d]]=[k.photos[i+d],k.photos[i]];renderPhotos();}\n    renderPhotos();\n    $(\"#profile-upload\").onchange=e=>{const files=[...e.target.files];for(const file of files){if(![\"image/jpeg\",\"image/png\",\"image/webp\",\"image/gif\"].includes(file.type)){alert(\"Please choose a JPG, PNG, WEBP, or GIF image.\");continue;}if(file.size>20*1024*1024){alert(\"Please choose a photo smaller than 20 MB.\");continue;}const local=URL.createObjectURL(file);pendingPhotoUploads.set(local,{file,kittenId:String(k.id||\"kitten\")});k.photos.push(local);}renderPhotos();markDirty();e.target.value=\"\";};\n    $(\"#save-kitten-draft\").onclick=()=>{markDirty();renderKittenList();$(\"#save-status\").textContent=k.name+\" profile draft saved in this session. Not published.\";};\n  }\n  function options(values,current){return values.map(v=>`<option ${v===current?\"selected\":\"\"}>${esc(v)}</option>`).join(\"\");}\n  function dateForInput(value){const d=new Date(/^\\d{4}-\\d{2}-\\d{2}$/.test(value||\"\")?value+\"T12:00:00\":value);if(!value||Number.isNaN(d.getTime()))return \"\";return [d.getFullYear(),String(d.getMonth()+1).padStart(2,\"0\"),String(d.getDate()).padStart(2,\"0\")].join(\"-\");}\n  function dateForDisplay(value){if(!value)return \"\";const d=new Date(value+\"T12:00:00\");return Number.isNaN(d.getTime())?\"\":new Intl.DateTimeFormat(\"en-US\",{weekday:\"long\",month:\"long\",day:\"numeric\",year:\"numeric\"}).format(d);}\n  function isPastEvent(value){const d=new Date(value);if(!value||Number.isNaN(d.getTime()))return false;d.setHours(23,59,59,999);return d<new Date();}\n  function renderEvents(){\n    const e=draft.events,f=e.featuredEvent||(e.featuredEvent={}),s=e.specialEvent||(e.specialEvent={});\n    e.regularSchedule ||= {active:true,locations:[]};e.regularSchedule.locations ||= [];e.additionalSpecialEvents ||= [];\n    const comingSoon=isPastEvent(f.date);\n    const kittenChecks=draft.kittens.map(k=>{const checked=(f.attendingKittens||[]).includes(k.name);return `<label class=\"attending-option\"><input type=\"checkbox\" data-attending=\"${esc(k.name)}\" ${checked?\"checked\":\"\"}> ${esc(k.name)}</label>`;}).join(\"\");\n    const featuredFields=[[\"date\",\"Date\",\"date\"],[\"startTime\",\"Start time\",\"time\"],[\"endTime\",\"End time\",\"time\"],[\"time\",\"Display time\"],[\"location\",\"Location\"],[\"address\",\"Address\"],[\"mapsUrl\",\"Map link\"]].map(([key,label,type])=>`<label>${label}<input type=\"${type||\"text\"}\" data-featured=\"${key}\" value=\"${esc(key===\"date\"?dateForInput(f.dateISO||f[key]):f[key]||\"\")}\"></label>`).join(\"\");\n    const schedules=e.regularSchedule.locations.slice(0,2).map((loc,i)=>`<details class=\"editor-form collapsible\"><summary><span><h4>${esc(loc.name||\"Regular location \"+(i+1))}</h4><small class=\"muted\">${esc(loc.timing||\"Regular adoption location\")}</small></span><span class=\"collapse-indicator\" aria-hidden=\"true\">⌄</span></summary><div class=\"fields\">${[[\"name\",\"Location\"],[\"timing\",\"Schedule\"],[\"address\",\"Address\"],[\"mapsUrl\",\"Map link\"]].map(([key,label])=>`<label>${label}<input data-schedule=\"${i}:${key}\" value=\"${esc(loc[key]||\"\")}\"></label>`).join(\"\")}</div></details>`).join(\"\");\n    const specialList=[s,...e.additionalSpecialEvents].map((event,i)=>specialFields(event,i)).join(\"\");\n    $(\"#event-summary\").innerHTML=`<details class=\"editor-form collapsible\" id=\"featured-event-card\" open><summary><span><p class=\"eyebrow\">Where to Find Us</p><h3>Upcoming Adoption</h3><small class=\"muted\">${comingSoon?\"Coming Soon\":esc(f.date||\"Edit event details\")}</small></span><span class=\"collapse-indicator\" aria-hidden=\"true\">⌄</span></summary>${comingSoon?'<p class=\"notice\">This event date has passed. The public website will show the next event as coming soon until you update these details.</p>':\"\"}<label>Fill from saved location<select id=\"featured-location-preset\"><option value=\"\">Choose a saved location…</option>${LOCATION_PRESETS.map(p=>`<option value=\"${esc(p.id)}\">${esc(p.name)}</option>`).join(\"\")}</select></label><div class=\"fields\">${featuredFields}</div><h4>Kittens attending</h4><div class=\"fields attending-grid\">${kittenChecks}</div></details><h3>Special events</h3><div id=\"special-event-list\">${specialList}</div><button class=\"secondary\" id=\"add-special-event\" type=\"button\">+ Add another special event</button><h3>Regular adoption schedule</h3><p class=\"muted\">These two locations stay in place. You can update their times and details, but there are no extra location slots.</p>${schedules}<div class=\"editor-form\"><label>Schedule note<textarea id=\"schedule-note\" rows=\"2\">${esc(e.regularSchedule.note||\"\")}</textarea></label><button class=\"primary\" id=\"save-events\" type=\"button\">Save event draft</button></div>`;\n    $(\"#featured-location-preset\").addEventListener(\"change\",ev=>{const p=LOCATION_PRESETS.find(x=>x.id===ev.target.value);if(!p)return;applySavedLocation(f,p);renderEvents();markDirty();});\n    document.querySelectorAll(\"[data-featured]\").forEach(input=>input.addEventListener(\"input\",()=>{const key=input.dataset.featured;f[key]=key===\"date\"?dateForDisplay(input.value):input.value;if(key===\"date\")f.dateISO=input.value;}));\n    document.querySelectorAll(\"[data-attending]\").forEach(input=>input.addEventListener(\"change\",()=>{const name=input.dataset.attending;f.attendingKittens||=[];f.attendingKittens=input.checked?[...new Set([...f.attendingKittens,name])]:f.attendingKittens.filter(x=>x!==name);}));\n    document.querySelectorAll(\"[data-schedule]\").forEach(input=>input.addEventListener(\"input\",()=>{const [i,key]=input.dataset.schedule.split(\":\");e.regularSchedule.locations[Number(i)][key]=input.value;}));\n    $(\"#schedule-note\").addEventListener(\"input\",ev=>{e.regularSchedule.note=ev.target.value;});\n    document.querySelectorAll(\"[data-special]\").forEach(input=>input.addEventListener(\"input\",()=>{const [i,key]=input.dataset.special.split(\":\");(Number(i)===0?e.specialEvent:e.additionalSpecialEvents[Number(i)-1])[key]=key===\"date\"?dateForDisplay(input.value):input.value;if(key===\"date\")(Number(i)===0?e.specialEvent:e.additionalSpecialEvents[Number(i)-1]).dateISO=input.value;}));\n    document.querySelectorAll(\"[data-special-active]\").forEach(input=>input.addEventListener(\"change\",()=>{const i=Number(input.dataset.specialActive);(i===0?e.specialEvent:e.additionalSpecialEvents[i-1]).active=input.checked;}));\n    document.querySelectorAll(\"[data-special-location]\").forEach(input=>input.addEventListener(\"change\",()=>{const i=Number(input.dataset.specialLocation),target=i===0?e.specialEvent:e.additionalSpecialEvents[i-1],p=LOCATION_PRESETS.find(x=>x.id===input.value);if(p){applySavedLocation(target,p);renderEvents();markDirty();}}));\n    document.querySelectorAll(\"[data-special-template]\").forEach(input=>input.addEventListener(\"change\",()=>{const i=Number(input.dataset.specialTemplate),target=i===0?e.specialEvent:e.additionalSpecialEvents[i-1],p=EVENT_PRESETS.find(x=>x.id===input.value);if(p){const keepDate=target.date,keepISO=target.dateISO;Object.assign(target,clone(p.values),{date:keepDate,dateISO:keepISO});renderEvents();markDirty();}}));\n    document.querySelectorAll(\"[data-remove-special]\").forEach(button=>button.addEventListener(\"click\",()=>{e.additionalSpecialEvents.splice(Number(button.dataset.removeSpecial)-1,1);renderEvents();markDirty();}));\n    $(\"#add-special-event\").onclick=()=>{e.additionalSpecialEvents.push({active:true,title:\"\",description:\"\",location:\"\",date:\"\",dateISO:\"\",startTime:\"10:00\",endTime:\"16:00\",yogaStartTime:\"11:30\",time:\"\",adoptionTime:\"\",yogaTime:\"\",address:\"\",mapsUrl:\"\"});renderEvents();markDirty();};\n    $(\"#save-events\").onclick=()=>{markDirty();$(\"#save-status\").textContent=\"Event drafts saved in this session. Not published.\";};\n  }\n  const LOCATION_PRESETS=[\n    {id:\"pittsburg\",name:\"Pittsburg PetSmart\",location:\"Pittsburg PetSmart\",address:\"4655 Century Blvd, Pittsburg, CA 94565\",mapsUrl:\"https://maps.app.goo.gl/FSasx3ZRVWMepJCB7\"},\n    {id:\"antioch\",name:\"Antioch PetSmart\",location:\"Antioch PetSmart\",address:\"5879 Lone Tree Way, Antioch, CA 94531\",mapsUrl:\"https://maps.app.goo.gl/bDa3qbVxZ8EPSCqG6\",startTime:\"11:00\",endTime:\"15:00\",time:\"11 a.m. – 3 p.m.\"},\n    {id:\"brentwood\",name:\"Brentwood Farmers Market\",location:\"Brentwood Farmers Market\",address:\"In front of Hair Encounters | 614 1st St, Brentwood, CA\",mapsUrl:\"https://maps.app.goo.gl/V2cGFG6hthWMbo9m6\",startTime:\"08:00\",endTime:\"12:00\",time:\"8 a.m. – 12 p.m.\"},\n    {id:\"pet-food-express\",name:\"Pet Food Express — Antioch\",location:\"Pet Food Express\",address:\"5829 Lone Tree Way, Suite B, Antioch, CA 94531\",mapsUrl:\"https://www.google.com/maps/search/?api=1&query=Pet+Food+Express%2C+5829+Lone+Tree+Way%2C+Antioch%2C+CA+94531\",startTime:\"11:00\",endTime:\"14:00\",time:\"11 a.m. – 2 p.m.\"},\n    {id:\"diamond-hills\",name:\"Diamond Hills Sports Club & Spa\",location:\"Diamond Hills Sports Club & Spa\",address:\"1510 Neroly Road, Oakley, CA\",mapsUrl:\"https://www.google.com/maps/search/?api=1&query=Diamond+Hills+Sports+Club+%26+Spa%2C+1510+Neroly+Road%2C+Oakley%2C+CA\"}\n  ];\n  const EVENT_PRESETS=[{id:\"kitty-yoga\",name:\"Kitty Adoption Event & Yoga\",values:{active:true,title:\"Kitty Adoption Event & Yoga\",description:\"Join us for a kitten adoption event and Kitty Yoga. Add the date and event details for each occurrence.\",location:\"Diamond Hills Sports Club & Spa\",address:\"1510 Neroly Road, Oakley, CA\",mapsUrl:\"https://www.google.com/maps/search/?api=1&query=Diamond+Hills+Sports+Club+%26+Spa%2C+1510+Neroly+Road%2C+Oakley%2C+CA\",startTime:\"10:00\",endTime:\"16:00\",yogaStartTime:\"11:30\",adoptionTime:\"10 a.m. – 4 p.m.\",yogaTime:\"11:30 a.m.\",time:\"Adoption Event: 10 a.m. – 4 p.m. | Kitty Yoga: 11:30 a.m. (Members Only)\"}}];\n  function applySavedLocation(target,p){target.location=p.location;target.address=p.address;target.mapsUrl=p.mapsUrl;if(p.startTime){target.startTime=p.startTime;target.endTime=p.endTime;target.time=p.time;if(\"adoptionTime\" in target)target.adoptionTime=p.time;}}\n  function specialFields(obj,index){\n    return `<details class=\"editor-form collapsible\" ${index===0?\"open\":\"\"}><summary><span><p class=\"eyebrow\">${index===0?\"Special event\":\"Additional event\"}</p><h4>${esc(obj.title||\"Special event\")}</h4><small class=\"muted\">${esc(obj.location||\"Add event details\")}</small></span><span class=\"collapse-indicator\" aria-hidden=\"true\">⌄</span></summary><div class=\"form-heading\">${index>0?'<button type=\"button\" class=\"quiet\" data-remove-special=\"'+index+'\">Remove event</button>':\"\"}</div><label>Saved event setup<select data-special-template=\"${index}\"><option value=\"\">Choose a saved event setup…</option>${EVENT_PRESETS.map(p=>'<option value=\"'+esc(p.id)+'\">'+esc(p.name)+'</option>').join(\"\")}</select></label><label>Fill from saved location<select data-special-location=\"${index}\"><option value=\"\">Choose a saved location…</option>${LOCATION_PRESETS.map(p=>'<option value=\"'+esc(p.id)+'\">'+esc(p.name)+'</option>').join(\"\")}</select></label><label><input type=\"checkbox\" data-special-active=\"${index}\" ${obj.active!==false?\"checked\":\"\"}> Show this event on the public website</label><div class=\"fields\">${[[\"title\",\"Event title\"],[\"date\",\"Date\",\"date\"],[\"startTime\",\"Adoption event start\",\"time\"],[\"endTime\",\"Adoption event end\",\"time\"],[\"yogaStartTime\",\"Kitty Yoga start\",\"time\"],[\"location\",\"Location\"],[\"adoptionTime\",\"Adoption activity display\"],[\"yogaTime\",\"Yoga display\"],[\"time\",\"Other time details\"],[\"address\",\"Address\"],[\"mapsUrl\",\"Map link\"]].map(([key,label,type])=>`<label>${label}<input type=\"${type||\"text\"}\" data-special=\"${index}:${key}\" value=\"${esc(key===\"date\"?dateForInput(obj.dateISO||obj[key]):obj[key]||\"\")}\"></label>`).join(\"\")}</div><label>Description<textarea rows=\"3\" data-special=\"${index}:description\">${esc(obj.description||\"\")}</textarea></label></details>`;\n  }\nfunction renderPhotos(){\n    $(\"#hero-photo-list\").innerHTML=draft.heroPhotos.map((p,i)=>{const src=String(p).startsWith(\"blob:\")?p:\"https://pawsandpurrfostersHQ.github.io/pawsandpurrfosters.com/assets/hero/\"+p;return `<div class=\"photo-row\"><img src=\"${esc(src)}\" alt=\"Homepage carousel photo ${i+1}\"><span class=\"photo-file-label\" title=\"${esc(String(p).split(\"/\").pop())}\"><strong>${i+1}.</strong> Homepage photo</span><button type=\"button\" data-hero-up=\"${i}\" ${i===0?\"disabled\":\"\"}>↑</button><button type=\"button\" data-hero-down=\"${i}\" ${i===draft.heroPhotos.length-1?\"disabled\":\"\"}>↓</button><button type=\"button\" data-hero-remove=\"${i}\">Remove</button></div>`;}).join(\"\")||\"<p>No homepage photos are configured yet.</p>\";\n    document.querySelectorAll(\"[data-hero-up]\").forEach(b=>b.onclick=()=>heroMove(+b.dataset.heroUp,-1));\n    document.querySelectorAll(\"[data-hero-down]\").forEach(b=>b.onclick=()=>heroMove(+b.dataset.heroDown,1));\n    document.querySelectorAll(\"[data-hero-remove]\").forEach(b=>b.onclick=()=>{const p=draft.heroPhotos.splice(+b.dataset.heroRemove,1)[0];if(String(p).startsWith(\"blob:\")){URL.revokeObjectURL(p);pendingHeroPhotoUploads.delete(p);}renderPhotos();markDirty();});\n  }\n  function heroMove(i,d){[draft.heroPhotos[i],draft.heroPhotos[i+d]]=[draft.heroPhotos[i+d],draft.heroPhotos[i]];renderPhotos();markDirty();}\n  $(\"#hero-upload\").addEventListener(\"change\",event=>{for(const file of [...event.target.files]){if(![\"image/jpeg\",\"image/png\",\"image/webp\",\"image/gif\"].includes(file.type)){alert(\"Please choose a JPG, PNG, WEBP, or GIF image.\");continue;}if(file.size>20*1024*1024){alert(\"Please choose a photo smaller than 20 MB.\");continue;}const local=URL.createObjectURL(file);pendingHeroPhotoUploads.set(local,{file});draft.heroPhotos.push(local);}renderPhotos();markDirty();event.target.value=\"\";});\n  function renderAlumni(){\n    $(\"#alumni-summary\").innerHTML=`<div class=\"notice\">${draft.alumni.length} existing alumni records are loaded from your website. Select any record to edit it.</div><div id=\"alumni-records\" class=\"record-list\">${draft.alumni.map(k=>`<button type=\"button\" class=\"record\" data-alumni=\"${esc(k.id)}\"><img src=\"${esc(\"https://pawsandpurrfostersHQ.github.io/pawsandpurrfosters.com/\")}${esc(k.image||\"\")}\" alt=\"\"><span><strong>${esc(k.name)}</strong><small>${esc(k.adoptionDate||\"Adoption date not entered\")}</small></span></button>`).join(\"\")}</div><div id=\"alumni-editor\"></div><div id=\"alumni-celebration-preview\"></div>`;\n    document.querySelectorAll(\"[data-alumni]\").forEach(b=>b.addEventListener(\"click\",()=>editAlumni(b.dataset.alumni)));\n  }\n  function editAlumni(id){\n    const k=draft.alumni.find(x=>x.id===id);if(!k)return;const box=$(\"#alumni-editor\");\n    box.innerHTML=`<section class=\"editor-form\"><div class=\"form-heading\"><div><p class=\"eyebrow\">Foster alumni record</p><h3>${esc(k.name)}</h3></div><button type=\"button\" class=\"quiet\" id=\"close-alumni\">Close</button></div><div class=\"fields\">${[[\"name\",\"Name\"],[\"gender\",\"Gender\"],[\"birthday\",\"Birthday\",\"date\"],[\"adoptionDate\",\"Gotcha day / adoption date\",\"date\"],[\"fosterLitter\",\"Foster litter\",\"number\"],[\"image\",\"Main photo path\"],[\"companionId\",\"Companion ID\"]].map(([key,label,type])=>`<label>${label}<input data-alumni=\"${key}\" type=\"${type||\"text\"}\" value=\"${esc(k[key]||\"\")}\"></label>`).join(\"\")}</div><label>Additional photo paths (one per line)<textarea rows=\"3\" data-alumni=\"photos\">${esc((k.photos||[]).join(\"\\\n\"))}</textarea></label><div class=\"fields\"><label><input type=\"checkbox\" data-alumni-flag=\"fosterFail\" ${k.fosterFail?\"checked\":\"\"}> Foster fail</label><label><input type=\"checkbox\" data-alumni-flag=\"secondChance\" ${k.secondChance?\"checked\":\"\"}> Second Chance</label></div><button type=\"button\" class=\"primary\" id=\"save-alumni\">Save alumni draft</button></section>`;\n    box.querySelectorAll(\"[data-alumni]\").forEach(input=>input.addEventListener(\"input\",()=>{const key=input.dataset.alumni;k[key]=key===\"fosterLitter\"?Number(input.value):key===\"photos\"?input.value.split(\"\\\n\").map(x=>x.trim()).filter(Boolean):input.value;}));\n    box.querySelectorAll(\"[data-alumni-flag]\").forEach(input=>input.addEventListener(\"change\",()=>{k[input.dataset.alumniFlag]=input.checked;}));\n    $(\"#close-alumni\").onclick=()=>{box.innerHTML=\"\";$(\"#alumni-celebration-preview\").innerHTML=\"\";};\n    $(\"#save-alumni\").onclick=()=>{markDirty();renderAlumni();editAlumni(id);$(\"#save-status\").textContent=k.name+\" alumni draft saved in this session. Not published.\";};\n    renderCelebrationPreview(k);\n    requestAnimationFrame(()=>box.scrollIntoView({behavior:\"smooth\",block:\"start\"}));\n  }\n  function renderCelebrationPreview(k){\n    const birthdayMonth=k.birthday?new Date(k.birthday+\"T12:00:00\").toLocaleString(\"en-US\",{month:\"long\"}):\"their birthday\";\n    $(\"#alumni-celebration-preview\").innerHTML=`<section class=\"editor-form\"><p class=\"eyebrow\">Celebration preview</p><h3>How ${esc(k.name)} appears on the alumni page</h3><div class=\"record-list\"><div class=\"summary-item\"><span class=\"alumni-birthday-cake\">🎂</span><strong> Birthday month</strong><p class=\"muted\">A little cake appears on the photo during ${esc(birthdayMonth)}.</p></div><div class=\"summary-item\"><strong>Happy Birthday, ${esc(k.name)}!</strong><p class=\"muted\">Shown on ${esc(k.birthday||\"their birthday\")}.</p></div><div class=\"summary-item\"><strong>Happy Gotcha Day, ${esc(k.name)}!</strong><p class=\"muted\">Shown on ${esc(k.adoptionDate||\"their gotcha day\")}.</p></div></div><p class=\"muted\">These are previews only; the live page will display the matching celebration on the correct date.</p></section>`;\n  }\n\n  const previewFrame = $(\"#preview-frame\");\n  const previewOrigin = \"https://pawsandpurrfostershq.github.io\";\n  const previewSiteUrl = \"https://pawsandpurrfostersHQ.github.io/pawsandpurrfosters.com/\";\n  let previewFrameReady = false, previewFrameStarted = false, pendingPreviewDraft = null;\n  function sendPreviewDraft() {\n    if (!previewFrameReady || !pendingPreviewDraft || !previewFrame.contentWindow) return;\n    previewFrameReady = false;\n    previewFrame.contentWindow.postMessage({ type:\"paws-preview-set-draft\", draft:pendingPreviewDraft }, previewOrigin);\n  }\n  window.addEventListener(\"message\", event => {\n    if (event.origin !== previewOrigin || event.source !== previewFrame.contentWindow) return;\n    const message = event.data || {};\n    if (message.type === \"paws-preview-ready\") {\n      previewFrameReady = true;\n      if (pendingPreviewDraft) sendPreviewDraft();\n    } else if (message.type === \"paws-preview-saved\") {\n      pendingPreviewDraft = null;\n      previewFrameReady = false;\n      $(\"#save-status\").textContent = \"Website preview updated. Nothing has been published.\";\n    } else if (message.type === \"paws-preview-cleared\") {\n      previewFrameReady = true;\n    } else if (message.type === \"paws-preview-error\") {\n      pendingPreviewDraft = null;\n      previewFrameReady = true;\n      $(\"#save-status\").textContent = message.message || \"The website preview could not be updated.\";\n    }\n  });\n\n  async function buildPreviewDraft() {\n    const snapshot = clone({ kittens:draft.kittens, events:draft.events, alumni:draft.alumni, heroPhotos:draft.heroPhotos });\n    const cache = new Map();\n    let totalBytes = 0;\n    async function convert(value) {\n      if (typeof value === \"string\" && value.startsWith(\"blob:\")) {\n        if (cache.has(value)) return cache.get(value);\n        const pending = pendingPhotoUploads.get(value) || pendingHeroPhotoUploads.get(value);\n        if (!pending?.file) throw new Error(\"A newly added photo is no longer available. Please select it again before previewing.\");\n        const prepared = await preparePhoto(pending.file);\n        const dataUrl = await new Promise((resolve,reject) => {\n          const reader = new FileReader();\n          reader.onload = () => resolve(String(reader.result));\n          reader.onerror = () => reject(new Error(\"Could not prepare a new photo for preview.\"));\n          reader.readAsDataURL(prepared.file);\n        });\n        totalBytes += dataUrl.length;\n        if (totalBytes > 4300000) throw new Error(\"Your new preview photos are too large to load together. Please preview with fewer new photos at a time.\");\n        cache.set(value,dataUrl);\n        return dataUrl;\n      }\n      if (Array.isArray(value)) return Promise.all(value.map(convert));\n      if (value && typeof value === \"object\") {\n        const entries = await Promise.all(Object.entries(value).map(async ([key,item]) => [key,await convert(item)]));\n        return Object.fromEntries(entries);\n      }\n      return value;\n    }\n    return await convert(snapshot);\n  }\n\n  $(\"#preview\").onclick = async () => {\n    const button = $(\"#preview\");\n    button.disabled = true;\n    $(\"#save-status\").textContent = \"Preparing your latest website preview…\";\n    try {\n      pendingPreviewDraft = await buildPreviewDraft();\n      $(\"#preview-dialog\").showModal();\n      if (!previewFrameStarted) {\n        previewFrameStarted = true;\n        previewFrame.src = previewSiteUrl + \"?paws-preview=1\";\n      } else {\n        sendPreviewDraft();\n      }\n    } catch (error) {\n      pendingPreviewDraft = null;\n      $(\"#save-status\").textContent = error.message || \"Could not prepare the website preview.\";\n    } finally {\n      button.disabled = false;\n    }\n  };\n  $(\"#preview-desktop\").onclick = () => previewFrame.classList.remove(\"is-mobile\");\n  $(\"#preview-mobile\").onclick = () => previewFrame.classList.add(\"is-mobile\");\n  $(\"#close-preview\").onclick = () => {\n    if (previewFrame.contentWindow) previewFrame.contentWindow.postMessage({type:\"paws-preview-clear\"},previewOrigin);\n    pendingPreviewDraft = null;\n    $(\"#preview-dialog\").close();\n  };\n  const publishButton = $(\"#publish\");\n  publishButton.disabled = true;\n\n  function replaceAssignedArray(source, assignment, value) {\n    const start = source.indexOf(assignment);\n    const end = source.indexOf(\"];\", start);\n    if (start < 0 || end < 0) throw new Error(\"Could not prepare \" + assignment + \" for saving.\");\n    return source.slice(0, start) + assignment + \" = \" + JSON.stringify(value, null, 2) + \";\" + source.slice(end + 2);\n  }\n\n  const pendingPhotoUploads = new Map();\n  const pendingHeroPhotoUploads = new Map();\n\n  async function photoToBase64(file) {\n    const dataUrl = await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error(\"Could not read one of the selected photos.\"));reader.readAsDataURL(file);});\n    return String(dataUrl).split(\",\")[1] || \"\";\n  }\n\n  async function preparePhoto(file) {\n    if (!window.createImageBitmap) {\n      if (file.size > 3 * 1024 * 1024) throw new Error(\"This photo is too large for a reliable upload. Please choose a smaller image (under 3 MB).\");\n      return { file, contentType:file.type };\n    }\n    const bitmap = await createImageBitmap(file);\n    const scale = Math.min(1, 1600 / Math.max(bitmap.width, bitmap.height));\n    const canvas = document.createElement(\"canvas\");\n    canvas.width = Math.max(1, Math.round(bitmap.width * scale));\n    canvas.height = Math.max(1, Math.round(bitmap.height * scale));\n    canvas.getContext(\"2d\").drawImage(bitmap, 0, 0, canvas.width, canvas.height);\n    bitmap.close?.();\n    const blob = await new Promise(resolve=>canvas.toBlob(resolve,\"image/jpeg\",0.78));\n    if (!blob || blob.size > 4 * 1024 * 1024) throw new Error(\"This photo could not be compressed small enough. Please choose another image.\");\n    return { file:new File([blob],file.name.replace(/\\\\.[^.]+$/,\"\")+\".jpg\",{type:\"image/jpeg\"}), contentType:\"image/jpeg\" };\n  }\n\n  async function buildDraftFiles() {\n    const [kittenSource, eventSource, alumniSource, scriptSource] = await Promise.all([\n      fetch(\"https://pawsandpurrfostersHQ.github.io/pawsandpurrfosters.com/kitten-data.js\", { cache: \"no-store\" }).then(r => { if (!r.ok) throw new Error(\"Could not load kitten data.\"); return r.text(); }),\n      fetch(\"https://pawsandpurrfostersHQ.github.io/pawsandpurrfosters.com/event-data.js\", { cache: \"no-store\" }).then(r => { if (!r.ok) throw new Error(\"Could not load event data.\"); return r.text(); }),\n      fetch(\"https://pawsandpurrfostersHQ.github.io/pawsandpurrfosters.com/alumni-data.js\", { cache: \"no-store\" }).then(r => { if (!r.ok) throw new Error(\"Could not load alumni data.\"); return r.text(); }),\n      fetch(\"https://pawsandpurrfostersHQ.github.io/pawsandpurrfosters.com/script.js\", { cache: \"no-store\" }).then(r => { if (!r.ok) throw new Error(\"Could not load homepage settings.\"); return r.text(); })\n    ]);\n    const uploads = [];\n    const photoMap = {};\n    const heroPhotosDraft = [...draft.heroPhotos];\n    const kittensDraft = clone(draft.kittens);\n    for (const kitten of kittensDraft) {\n      kitten.photos = await Promise.all((kitten.photos || []).map(async photo => {\n        if (!String(photo).startsWith(\"blob:\")) return photo;\n        const pending = pendingPhotoUploads.get(photo);\n        if (!pending) throw new Error(\"A selected photo is no longer available. Please choose it again.\");\n        const prepared = await preparePhoto(pending.file);\n        const ext = \"jpg\";\n        const safeId = String(kitten.id || pending.kittenId || \"kitten\").toLowerCase().replace(/[^a-z0-9-]+/g,\"-\").replace(/^-|-$/g,\"\").slice(0,40) || \"kitten\";\n        const filename = `${safeId}-${Date.now()}-${uploads.length+1}.${ext}`;\n        const savedPath = `assets/kittens/${filename}`;\n        const contentBase64 = await photoToBase64(prepared.file);\n        const totalUploadSize = uploads.reduce((sum,item)=>sum+item.contentBase64.length,0) + contentBase64.length;\n        if (totalUploadSize > 5_000_000) throw new Error(\"These photos are too large to send together. Publish fewer new photos at a time.\");\n        uploads.push({ path:savedPath, contentType:prepared.contentType, contentBase64 });\n        photoMap[photo] = savedPath;\n        return savedPath;\n      }));\n    }\n    for(let i=0;i<heroPhotosDraft.length;i++){\n      const photo=heroPhotosDraft[i];if(!String(photo).startsWith(\"blob:\"))continue;\n      const pending=pendingHeroPhotoUploads.get(photo);if(!pending)throw new Error(\"A selected homepage photo is no longer available. Please choose it again.\");\n      const prepared=await preparePhoto(pending.file),filename=`hero-${Date.now()}-${uploads.length+1}.jpg`,savedPath=`assets/hero/${filename}`;\n      const contentBase64=await photoToBase64(prepared.file),totalUploadSize=uploads.reduce((sum,item)=>sum+item.contentBase64.length,0)+contentBase64.length;\n      if(totalUploadSize>5_000_000)throw new Error(\"These photos are too large to send together. Publish fewer new photos at a time.\");\n      uploads.push({path:savedPath,contentType:prepared.contentType,contentBase64});heroPhotosDraft[i]=filename;\n    }\n    const kittens = replaceAssignedArray(kittenSource, \"appRoot.PAWS_KITTENS\", kittensDraft);\n    const eventsMatch = eventSource.match(/window\\.PAWS_EVENT_DATA\\s*=\\s*\\{[\\s\\S]*\\};\\s*$/);\n    if (!eventsMatch) throw new Error(\"Could not prepare event data for saving.\");\n    const events = eventSource.replace(eventsMatch[0], \"window.PAWS_EVENT_DATA = \" + JSON.stringify(draft.events, null, 2) + \";\\\n\");\n    const alumni = replaceAssignedArray(alumniSource, \"alumniRoot.PAWS_FOSTER_ALUMNI\", draft.alumni);\n    const hero = replaceAssignedArray(scriptSource, \"const FOSTER_CAROUSEL_PHOTOS\", heroPhotosDraft);\n    return { files: { \"kitten-data.js\": kittens, \"event-data.js\": events, \"alumni-data.js\": alumni, \"script.js\": hero }, uploads, photoMap, heroPhotosDraft };\n  }\n\n  publishButton.addEventListener(\"click\", async () => {\n    if (!supabaseClient || publishButton.disabled) return;\n    if (!window.confirm(\"Publish these approved changes to the live Paws & Purr website?\")) return;\n    publishButton.disabled = true;\n    $(\"#save-status\").textContent = \"Sending your approved draft to the private branch…\";\n    try {\n      const draftPayload = await buildDraftFiles();\n      const { data, error } = await supabaseClient.functions.invoke(\"publish-draft\", {\n        body: { ...draftPayload, message: \"Update foster website draft from private editor\" }\n      });\n      if (error) {\n        let detail = error.message || \"Publishing request failed.\";\n        try { const body = await error.context?.json(); if (body?.error) detail = body.error; } catch {}\n        throw new Error(detail);\n      }\n      if (!data?.ok || data.branch !== \"main\") {\n        throw new Error(data?.error || \"The service did not confirm a private-branch save.\");\n      }\n      let eventConflictWarning = \"\";\n      try { const sync = await supabaseClient.functions.invoke(\"event-conflicts\", { body: { action: \"sync-events\", events: draft.events } }); if (sync.error || !sync.data?.ok) eventConflictWarning = \" Event-conflict emails could not be processed; please check the Meet & Greets tab.\"; } catch (_) { eventConflictWarning = \" Event-conflict emails could not be processed; please check the Meet & Greets tab.\"; }\n      for (const kitten of draft.kittens) kitten.photos = (kitten.photos || []).map(photo => {\n        const savedPath = draftPayload.photoMap[photo];\n        if (!savedPath) return photo;\n        URL.revokeObjectURL(photo);\n        pendingPhotoUploads.delete(photo);\n        return savedPath;\n      });\n      draft.heroPhotos = draftPayload.heroPhotosDraft;\n      for(const [local] of pendingHeroPhotoUploads){URL.revokeObjectURL(local);pendingHeroPhotoUploads.delete(local);}\n      renderPhotos();\n      renderKittenList();\n      dirty = false;\n      $(\"#save-status\").textContent = \"Changes published to the live website.\" + eventConflictWarning;\n    } catch (error) {\n      $(\"#save-status\").textContent = \"Draft was not confirmed as saved: \" + (error.message || \"Unknown error.\");\n      publishButton.disabled = false;\n    }\n  });\n\n  function updatePublishAvailability() { publishButton.disabled = !dirty || !supabaseClient; }\n  const originalMarkDirty = markDirty;\n  markDirty = () => { originalMarkDirty(); updatePublishAvailability(); };\n  renderKittenList();renderPhotos();renderEvents();renderAlumni();\n})();</script>\n</body></html>";
const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, apikey, x-client-info, content-type",
  "Access-Control-Allow-Methods": "GET, OPTIONS",
  "Vary": "Origin",
};
const htmlHeaders = {
  ...corsHeaders,
  "Content-Type": "text/html; charset=utf-8",
  "Cache-Control": "no-store",
  "X-Robots-Tag": "noindex, nofollow",
};
Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") return new Response("ok", { status: 200, headers: corsHeaders });
  if (req.method !== "GET") return new Response("Method not allowed", { status: 405, headers: corsHeaders });
  const url = new URL(req.url);
  if (url.searchParams.get("view") !== "app") return new Response(LOGIN_HTML, { headers: htmlHeaders });
  const token = req.headers.get("Authorization")?.replace(/^Bearer\s+/i, "");
  if (!token) return new Response("Unauthorized", { status: 401, headers: corsHeaders });
  const auth = await fetch(SUPABASE_URL + "/auth/v1/user", { headers: { apikey: SUPABASE_ANON_KEY, Authorization: "Bearer " + token } });
  if (!auth.ok) return new Response("Unauthorized", { status: 401, headers: corsHeaders });
  const user = await auth.json();
  if (String(user.email || "").toLowerCase() !== ADMIN_EMAIL) return new Response("Forbidden", { status: 403, headers: corsHeaders });
  return new Response(APP_HTML, { headers: htmlHeaders });
});